def run(inputs: Inputs) -> Outputs:
    severity = (inputs.severity or "").strip().lower()
    priority_sla = {
        "critical": ("P1", "2h"),
        "high": ("P2", "4h"),
        "medium": ("P3", "24h"),
        "low": ("P4", "72h"),
    }
    priority, sla = priority_sla.get(severity, ("P3", "24h"))

    signal = ((inputs.affected_area or "") + " " + (inputs.category or "")).lower()
    if any(k in signal for k in ("export", "billing", "payment", "invoice")):
        owner = "Billing squad"
    elif any(k in signal for k in ("auth", "login", "sso")):
        owner = "Platform squad"
    elif any(k in signal for k in ("ui", "render", "frontend")):
        owner = "Frontend squad"
    else:
        owner = "Triage / Support"

    title = (inputs.title or "Untitled issue").strip()
    summary = (inputs.summary or "").strip()
    category = (inputs.category or "bug").strip()
    sev = severity or "medium"

    lines = [
        "\U0001F916 ISSUE logged",
        "Title:    " + title,
        "Category: " + category + "   |   Severity: " + sev + "   |   Priority: " + priority + "   |   SLA: " + sla,
        "Owner:    " + owner,
        "Summary:  " + summary,
    ]
    return {"response": "\n".join(lines)}

def run(inputs: Inputs) -> Outputs:
    summary = (inputs.summary or "").strip()
    body = (
        "\U0001F916 This looks like it might be an issue, but I need a bit more "
        "detail to log it: which system, what you saw (error text or screenshot), "
        "and the steps to reproduce."
    )
    if summary:
        body = body + "\n\nWhat I understood so far: " + summary
    return {"response": body}
